// --- Issue #1: the ball bounces off bricks (was: plows straight through) ---
// Each behaviour below was first written as a red test, then made green by
// the sweep + per-face resolution in `brickHit`.

test('brickHit: bottom face hit flips vy only, leaves vx, pushes the ball out', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // row 0, col 0 → (4, 48, 72, 20)
  const ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 5, // 73: barely overlapping through the bottom face
    r: 7,
    vx: 40,
    vy: -300, // heading up into the brick
    px: brick.x + brick.w / 2,
    py: brick.y + brick.h + 22, // 90: started below the brick
  };

  const broken = brickHit(ball, state.bricks);

  assert.equal(broken.length, 1);
  assert.equal(brick.alive, false, 'the brick is broken');
  assert.equal(ball.vy, 300, 'vy flips (bottom face)');
  assert.equal(ball.vx, 40, 'vx is left exactly as it was');
  assert.ok(ball.y - ball.r > brick.y + brick.h, 'pushed out below the brick');
  assert.equal(collides(ball, brick), false, 'no overlap left (no sticky bounce)');
});

test('brickHit: top face hit flips vy only, leaves vx, pushes the ball out', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 6, // 42: barely overlapping through the top face
    r: 7,
    vx: 30,
    vy: 300, // heading down into the brick
    px: brick.x + brick.w / 2,
    py: brick.y - 20, // 28: started above the brick
  };

  brickHit(ball, state.bricks);

  assert.equal(ball.vy, -300, 'vy flips (top face)');
  assert.equal(ball.vx, 30, 'vx is left exactly as it was');
  assert.ok(ball.y + ball.r < brick.y, 'pushed out above the brick');
  assert.equal(collides(ball, brick), false);
});

test('brickHit: side hit flips vx only, leaves vy, pushes the ball out', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const ball = {
    x: brick.x - 2, // barely overlapping through the left face
    y: brick.y + brick.h / 2,
    r: 7,
    vx: 300, // heading right into the brick
    vy: -50,
    px: brick.x - 22, // started left of the brick
    py: brick.y + brick.h / 2,
  };

  brickHit(ball, state.bricks);

  assert.equal(ball.vx, -300, 'vx flips (side face)');
  assert.equal(ball.vy, -50, 'vy is left exactly as it was');
  assert.ok(ball.x + ball.r < brick.x, 'pushed out to the left of the brick');
  assert.equal(collides(ball, brick), false);
});

test('brickHit: corner hit (equal penetration) flips both components', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const ball = {
    x: brick.x - 4,
    y: brick.y - 4, // (0, 44): equal penetration on both axes
    r: 7,
    vx: 200,
    vy: -300,
    px: brick.x - 4,
    py: brick.y - 4,
  };

  brickHit(ball, state.bricks);

  assert.equal(ball.vx, -200, 'vx flips (diagonal hit)');
  assert.equal(ball.vy, 300, 'vy flips (diagonal hit)');
  assert.equal(collides(ball, brick), false, 'pushed out of the corner');
});

test('brickHit: no sticky bounce — the ball does not re-collide next frame', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 5,
    r: 7,
    vx: 40,
    vy: -300,
    px: brick.x + brick.w / 2,
    py: brick.y + brick.h + 22,
  };

  brickHit(ball, state.bricks);
  assert.equal(collides(ball, brick), false, 'pushed out after the first bounce');

  // Next frame: the ball moves away with its new velocity.
  ball.px = ball.x;
  ball.py = ball.y;
  ball.x += ball.vx * (1 / 60);
  ball.y += ball.vy * (1 / 60);

  const broken = brickHit(ball, state.bricks);
  assert.equal(broken.length, 0, 'no re-collision on the frame after the bounce');
  assert.equal(ball.vy, 300, 'vy was not flipped a second time');
});

test('brickHit: seam between two bricks breaks both with a single bounce', () => {
  const state = createState(1);
  const a = state.bricks[0]; // x: 4..76
  const b = state.bricks[1]; // x: 84..156 (8 px gap, ball is 14 px across)
  const mid = a.x + a.w + 4; // 80: dead center of the seam
  const ball = {
    x: mid,
    y: a.y + a.h + 6.5, // 74.5: overlaps both bottoms in the same pass
    r: 7,
    vx: 0,
    vy: -400,
    px: mid,
    py: a.y + a.h + 27, // 95: started below both
  };

  const broken = brickHit(ball, state.bricks);

  assert.equal(broken.length, 2, 'both seam bricks break');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.equal(ball.vy, 400, 'vy flips exactly once (a double flip would cancel out)');
  assert.equal(ball.vx, 0, 'vx untouched on a vertical seam shot');
  assert.equal(collides(ball, a), false);
  assert.equal(collides(ball, b), false);
});

test('brickHit: high-speed ball tunnels through a brick (sweep between positions)', () => {
  const state = createState(1);
  const brick = state.bricks[8]; // row 1: y 76..96
  const stepPx = ballSpeed(6) * 0.05; // 35.5 px per capped 50 ms frame
  assert.ok(stepPx > BRICK_H + 2 * BALL_R, 'one capped frame step crosses a brick (34 px)');

  const ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 7.5, // 68.5: already past the top edge, no overlap
    r: 7,
    vx: 0,
    vy: -ballSpeed(6),
    px: brick.x + brick.w / 2,
    py: brick.y + brick.h + 8, // 104: below the brick, no overlap either
  };

  // Neither endpoint overlaps the brick: only the sweep can see the hit.
  assert.equal(collides({ ...ball }, brick), false);
  assert.equal(collides({ x: ball.px, y: ball.py, r: ball.r }, brick), false);

  const broken = brickHit(ball, state.bricks);

  assert.equal(broken.length, 1, 'the swept segment crosses the brick');
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, ballSpeed(6), 'vy flips even though no position overlapped');
  assert.ok(ball.y - ball.r > brick.y + brick.h, 'ball parked just below the brick');
  assert.equal(collides(ball, brick), false);
});

test('frame: ball bounces off a brick and scores instead of plowing through', () => {
  const ctx = mockCtx();
  const state = createState(1);
  const brick = state.bricks[0];
  const ball = state.ball;

  ball.x = brick.x + brick.w / 2;
  ball.y = brick.y + brick.h + 12; // just below the brick
  ball.vx = 0;
  ball.vy = -400; // heading up into the brick

  step(state, 1 / 60); // the ball climbs into the brick
  frame(ctx, state); // collision resolved during the render pass

  assert.equal(brick.alive, false, 'brick breaks');
  assert.equal(ball.vy, 400, 'ball bounces back down');
  assert.equal(state.combo, 1);
  assert.equal(state.score, scoreForBrick(brick, 1));
  assert.equal(collides(ball, brick), false, 'ball pushed out');
});

// Minimal canvas context: `frame` only assigns styles and calls shape/text
// methods, so a stub is enough to drive the render loop in Node.
function mockCtx() {
  return {
    fillStyle: '',
    fillRect() {},
    fillText() {},
    beginPath() {},
    arc() {},
    fill() {},
  };
}

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

