export function step(state, dt) {
  const { ball, paddle } = state;

  // Record where the ball was before this step: brickHit() sweeps the path
  // from here to the new position (issue #1, anti-tunnelling).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
